import {
  format,
  differenceInDays,
  addDays,
  isBefore,
  startOfDay,
  isValid,
  parseISO,
} from "date-fns";
import { es } from "date-fns/locale";
import { CategoryId } from "./validation";

/**
 * Damage coverage rates by category
 */
export const DAMAGE_COVERAGE_RATES = {
  "fotografia-video": 0.2,
  "montana-camping": 0.1,
  "deportes-acuaticos": 0.1,
} as const;

/**
 * Get damage coverage rate for a category
 * 20% for photography and video, 10% for mountain and water sports
 */
export function getDamageCoverageRate(category?: string | CategoryId): number {
  if (!category) return 0;
  if (category in DAMAGE_COVERAGE_RATES) {
    return DAMAGE_COVERAGE_RATES[category as keyof typeof DAMAGE_COVERAGE_RATES];
  }
  const normalized = category.toLowerCase().trim();
  if (normalized.includes("fotografia") || normalized.includes("video")) {
    return 0.2;
  }
  if (
    normalized.includes("montana") ||
    normalized.includes("montaña") ||
    normalized.includes("camping") ||
    normalized.includes("acuatico") ||
    normalized.includes("acuático")
  ) {
    return 0.1;
  }
  return 0;
}

