/**
 * Round a currency amount to two decimal places (half cent up)
 * and eliminate floating point representation errors.
 */
export function roundToTwoDecimals(num: number): number {
  return Math.round((num + Number.EPSILON) * 100) / 100;
}

/**
 * Calculate rental price breakdown
 */
export function calculateRentalPrice(
  dailyRateOrItem: number | { dailyRate: number; category?: CategoryId | string },
  startDateOrDays: Date | number,
  endDateOrCategory?: Date | CategoryId | string,
  categoryParam?: CategoryId | string
): {
  days: number;
  dailyRate: number;
  subtotal: number;
  coverage: number;
  damageCoverage: number;
  coverageRate: number;
  damageCoverageRate: number;
  coveragePercentage: number;
  damageCoveragePercentage: number;
  total: number;
  totalPrice: number;
} {
  let dailyRate: number;
  let category: string | undefined;
  let days: number;

  if (typeof dailyRateOrItem === "object" && dailyRateOrItem !== null) {
    dailyRate = dailyRateOrItem.dailyRate;
    category = dailyRateOrItem.category;
  } else {
    dailyRate = dailyRateOrItem;
  }

  if (typeof startDateOrDays === "number") {
    days = startDateOrDays;
    if (typeof endDateOrCategory === "string") {
      category = endDateOrCategory;
    }
  } else {
    const start = startDateOrDays;
    const end = endDateOrCategory instanceof Date ? endDateOrCategory : start;
    days = calculateRentalDays(start, end);
    if (typeof categoryParam === "string") {
      category = categoryParam;
    } else if (typeof endDateOrCategory === "string") {
      category = endDateOrCategory;
    }
  }

  const subtotal = roundToTwoDecimals(calculateTotalPrice(dailyRate, days));
  const coverageRate = category ? getDamageCoverageRate(category) : 0;
  const coveragePercentage = Math.round(coverageRate * 100);
  const coverage = roundToTwoDecimals(subtotal * coverageRate);
  const total = roundToTwoDecimals(subtotal + coverage);

  return {
    days,
    dailyRate,
    subtotal,
    coverage,
    damageCoverage: coverage,
    coverageRate,
    damageCoverageRate: coverageRate,
    coveragePercentage,
    damageCoveragePercentage: coveragePercentage,
    total,
    totalPrice: total,
  };
}

/**
 * Format price in Mexican Pesos
 */
export function formatPrice(amount: number): string {
  if (typeof amount !== "number" || isNaN(amount)) {
    return "$0";
  }
  const hasDecimals = amount % 1 !== 0;
  return new Intl.NumberFormat("es-MX", {
    style: "currency",
    currency: "MXN",
    minimumFractionDigits: hasDecimals ? 2 : 0,
    maximumFractionDigits: 2,
  }).format(amount);
}

